patch:
diff --git a/repro-no-loss-of-precision.js b/repro-no-loss-of-precision.js
new file mode 100644
index 0000000..9779dd2
--- /dev/null
+++ b/repro-no-loss-of-precision.js
@@ -0,0 +1,32 @@
+"use strict";
+
+/*
+ * Check for the report "no-loss-of-precision rule incorrectly flags 9.000e+3".
+ * Expected: `const test = 9.000e+3` (a value of exactly 9000) is not reported.
+ * Exits non-zero while the rule reports it, zero once it does not.
+ *
+ * Usage: node repro-no-loss-of-precision.js [literal]
+ * (an optional literal replaces 9.000e+3, e.g. to run the check on an input without the trigger)
+ */
+
+const { Linter } = require("./lib/api");
+
+const literal = process.argv[2] || "9.000e+3";
+const code = `const test = ${literal} // ${Number(literal)}`;
+
+const messages = new Linter().verify(code, {
+	rules: { "no-loss-of-precision": "error" },
+});
+
+console.log(`code: ${code}`);
+console.log(
+	`reported: ${JSON.stringify(messages.map(m => `${m.line}:${m.column} ${m.message}`))}`,
+);
+
+if (messages.length > 0) {
+	console.error(
+		`FAIL: no-loss-of-precision reports ${literal}, which is exactly ${Number(literal)}`,
+	);
+	process.exit(1);
+}
+console.log("OK: no report");
